/**
 * Deployment fragments → `packages/clients` (plan C.1.6). Ported in spirit from Masayume 68f7a09:contracts/export.mjs,
 * extended to schema-v1 fragments per area and network.
 *
 *   node scripts/codegen/clients.mjs          write the generated files
 *   node scripts/codegen/clients.mjs --check  fail if the committed files differ from what would be generated
 *
 * Reads `contracts/deployments/<chainId>/<area>.json` and the ABIs in `contracts/out/<tempo|evm>/` (run the contracts
 * build first). Writes `packages/clients/src/{abis/<Name>.ts, deployments.ts, events.ts, indexer.ts, relay-targets.ts,
 * manifest.json}`. Nothing else in the monorepo reads `contracts/out` or `contracts/deployments` directly.
 */
import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const deploymentsDir = join(root, "contracts", "deployments");
const outDir = join(root, "contracts", "out");
const target = join(root, "packages", "clients", "src");
const check = process.argv.includes("--check");
const HEADER = "// Generated by scripts/codegen/clients.mjs — do not edit.\n";
const { keccak256, toBytes } = await import(createRequire(join(root, "scripts", "package.json")).resolve("viem"));

function fail(message) {
  console.error(`codegen: ${message}`);
  process.exit(1);
}

function readFragments() {
  if (!existsSync(deploymentsDir)) return [];
  const fragments = [];
  for (const chain of readdirSync(deploymentsDir).filter((d) => /^\d+$/.test(d)).sort()) {
    for (const file of readdirSync(join(deploymentsDir, chain)).filter((f) => f.endsWith(".json") && !f.endsWith(".pending.json")).sort()) {
      const path = join(deploymentsDir, chain, file);
      const fragment = JSON.parse(readFileSync(path, "utf8"));
      if (fragment.schema !== 1) fail(`${path}: schema must be 1`);
      if (String(fragment.chainId) !== chain) fail(`${path}: chainId ${fragment.chainId} ≠ directory ${chain}`);
      if (`${fragment.area}.json` !== file) fail(`${path}: area "${fragment.area}" ≠ file name`);
      for (const [name, c] of Object.entries(fragment.contracts ?? {})) {
        if (!/^0x[0-9a-fA-F]{40}$/.test(c.address ?? "")) fail(`${path}: ${name}.address is not an address`);
        if (!c.artifact?.includes(":")) fail(`${path}: ${name}.artifact must be "File.sol:Name"`);
      }
      fragments.push(fragment);
    }
  }
  return fragments;
}

function loadAbi(artifact, profile) {
  const [file, name] = artifact.split(":");
  const path = join(outDir, profile === "evm" ? "evm" : "tempo", file, `${name}.json`);
  if (!existsSync(path)) fail(`missing ${path} — run \`pnpm contracts:build\` first`);
  return JSON.parse(readFileSync(path, "utf8")).abi;
}

const ident = (name) => name.charAt(0).toLowerCase() + name.slice(1);

/**
 * ABIs the app needs that no fragment records (R4-12, D-227): the Robinhood testnet side of the bridge (it waits on the
 * owner's test ETH, but `/bridge`, `/reserves` and the ops watchers are built against it now), the LayerZero endpoint's
 * compose surface (a stored compose is re-run) and TIP-20 roles (the reserve check's ISSUER_ROLE scan). Generated from
 * the compiled artifacts like every other ABI; a deployed fragment with the same contract supersedes its entry.
 */
const EXTRA_ABIS = [
  { artifact: "StockLockbox.sol:StockLockbox", profile: "evm" },
  { artifact: "StockSyncSender.sol:StockSyncSender", profile: "evm" },
  { artifact: "ILayerZeroEndpointV2.sol:ILayerZeroEndpointV2", profile: "evm" },
  { artifact: "ITIP20RolesAuth.sol:ITIP20RolesAuth", profile: "tempo" },
];

function generate(fragments) {
  const files = new Map();
  const abis = new Map();
  for (const f of fragments) for (const [name, c] of Object.entries(f.contracts ?? {})) {
    const contractName = c.artifact.split(":")[1];
    if (!abis.has(contractName)) abis.set(contractName, loadAbi(c.artifact, c.profile));
  }
  for (const c of EXTRA_ABIS) {
    const contractName = c.artifact.split(":")[1];
    if (!abis.has(contractName)) abis.set(contractName, loadAbi(c.artifact, c.profile));
  }
  for (const [name, abi] of [...abis].sort(([a], [b]) => a.localeCompare(b))) {
    // One ABI entry per line: readable in a diff and inside the file-length invariant for most contracts.
    const entries = abi.map((entry) => `  ${JSON.stringify(entry)},`).join("\n");
    files.set(`abis/${name}.ts`, `${HEADER}export const ${ident(name)}Abi = [\n${entries}\n] as const;\n`);
  }
  const deployments = {};
  const relayTargets = {};
  for (const f of fragments) {
    deployments[f.chainId] ??= {};
    deployments[f.chainId][f.area] = { contracts: f.contracts, roles: f.roles ?? {}, params: f.params ?? {}, external: f.external ?? {}, commit: f.commit ?? null };
    relayTargets[f.chainId] ??= {};
    relayTargets[f.chainId][f.area] = Object.values(f.contracts ?? {}).map((c) => c.address);
  }
  files.set("deployments.ts", `${HEADER}export const deployments = ${JSON.stringify(deployments, null, 2)} as const;\n`);
  files.set("relay-targets.ts", `${HEADER}/** Contract addresses per chain and area; relay policies allowlist from here. */\nexport const relayTargets = ${JSON.stringify(relayTargets, null, 2)} as const;\n`);
  const events = {};
  for (const [name, abi] of abis) events[name] = abi.filter((e) => e.type === "event").map((e) => `${e.name}(${e.inputs.map((i) => i.type).join(",")})`);
  files.set("events.ts", `${HEADER}/** Event signatures per contract, for the indexer's sources. */\nexport const events = ${JSON.stringify(events, null, 2)} as const;\n`);
  // Indexer sources (plan C.4.1/C.4.3): per chain, every deployed contract with its deploy block and each event as a
  // full signature (`indexed` + names — the Tempo Indexer API / tidx `signature=` decodes columns from it) and topic0.
  const param = (i) => `${i.type}${i.indexed ? " indexed" : ""}${i.name ? ` ${i.name}` : ""}`;
  const canonical = (e) => `${e.name}(${e.inputs.map((i) => i.type).join(",")})`;
  const indexer = {};
  for (const f of fragments) for (const [name, c] of Object.entries(f.contracts ?? {})) {
    const abi = abis.get(c.artifact.split(":")[1]);
    const evs = abi.filter((e) => e.type === "event" && !e.anonymous);
    if (!evs.length) continue;
    indexer[f.chainId] ??= [];
    indexer[f.chainId].push({
      area: f.area,
      contract: name,
      address: c.address,
      deployBlock: c.deployBlock ?? null,
      events: evs.map((e) => ({ name: e.name, signature: `${e.name}(${e.inputs.map(param).join(", ")})`, topic0: keccak256(toBytes(canonical(e))) })),
    });
  }
  // One event per line keeps the generated file inside the file-length invariant as areas are deployed.
  const body = Object.entries(indexer).map(([chain, sources]) => `  "${chain}": [\n${sources.map((src) => {
    const { events: evs, ...head } = src;
    return `    {\n${Object.entries(head).map(([k, v]) => `      ${k}: ${JSON.stringify(v)},`).join("\n")}\n      events: [\n${evs.map((e) => `        ${JSON.stringify(e)},`).join("\n")}\n      ],\n    },`;
  }).join("\n")}\n  ],`).join("\n");
  files.set("indexer.ts", `${HEADER}/** Indexer sources per chain: deployed contracts, deploy blocks, full event signatures + topic0 (recount, tidx \`signature=\`). */\nexport const indexerSources = {\n${body}\n} as const;\n`);
  const manifest = { generatedBy: "scripts/codegen/clients.mjs", fragments: fragments.map((f) => `${f.chainId}/${f.area}`), abis: [...abis.keys()].sort() };
  files.set("manifest.json", `${JSON.stringify(manifest, null, 2)}\n`);
  return files;
}

const files = generate(readFragments());
const existingAbis = existsSync(join(target, "abis")) ? readdirSync(join(target, "abis")).map((f) => `abis/${f}`) : [];
const stale = existingAbis.filter((f) => !files.has(f));

if (check) {
  const drift = [...files].filter(([rel, body]) => !existsSync(join(target, rel)) || readFileSync(join(target, rel), "utf8") !== body).map(([rel]) => rel);
  if (drift.length || stale.length) fail(`generated clients are out of date: ${[...drift, ...stale].join(", ")} — run \`pnpm codegen\``);
  console.log(`codegen: up to date (${files.size} files)`);
} else {
  mkdirSync(join(target, "abis"), { recursive: true });
  for (const rel of stale) rmSync(join(target, rel));
  for (const [rel, body] of files) writeFileSync(join(target, rel), body);
  console.log(`codegen: wrote ${files.size} files (${[...files.keys()].filter((f) => f.startsWith("abis/")).length} ABIs)`);
}
